# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: gather
def gather(xs, factor=2):
    return [v * factor for v in xs]

# region: fold
def fold(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: digest
def digest(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (min(xs) - min(xs)) if xs else 0}

# region: intake
def intake(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return intake(digest(fold(gather(shape(raw)))))

